// ===== File: index.js — lazy loader and typed facade over the TentaQuant wasm simulator =====
//
// The browser tier (T0) of TentaQuant: the same OpenQASM 3 front end, circuit IR
// and state-vector simulator Core runs, compiled to wasm32. The glue is served
// from the dashboard's own origin and nowhere else — no CDN — and nothing loads
// until something asks for it, because it is ~900 KB of wasm that only the
// circuit Studio and the run view need.
//
// `quantum_glue.js` / `quantum_glue_bg.wasm` are generated by
// tentaflow-core/build.rs and are NOT in the repo. When they are missing the
// build skipped them, so `available()` answers false and the caller runs the
// circuit on T1 through the binary protocol instead.
//
// Values crossing the boundary follow two rules: anything sized 2^n (amplitudes,
// probabilities) arrives as a `Float64Array`, amplitudes interleaved
// `[re0, im0, re1, im1, ...]`; everything else arrives as a plain object.

// Bumped every time a trapped instance is thrown away, so the dynamic import
// yields a fresh module namespace instead of the poisoned one.
let instanceGeneration = 0;
let loading = null;
let glue = null;

async function load() {
  if (glue) return glue;
  if (!loading) {
    loading = (async () => {
      const mod = await import(`./quantum_glue.js?instance=${instanceGeneration}`);
      await mod.default();
      glue = mod;
      return mod;
    })().catch((err) => {
      loading = null;
      throw err;
    });
  }
  return loading;
}

/** Resolves once the simulator is usable; rejects when the glue is not built. */
export async function ready() {
  return load();
}

/**
 * Whether this build ships the browser simulator. `false` means the circuit has
 * to run on a node (T1), not that anything is broken.
 */
export async function available() {
  try {
    await load();
    return true;
  } catch {
    return false;
  }
}

/**
 * `wasm32-unknown-unknown` aborts on panic, so an upstream parser panic or an
 * allocation the wasm heap cannot serve traps the instance instead of unwinding.
 * A trapped instance can never be used again: it is dropped here and the next
 * call instantiates a fresh one, so one malformed circuit costs a reload of the
 * module, not a reload of the dashboard.
 */
function guard(call) {
  try {
    return call();
  } catch (err) {
    if (err instanceof WebAssembly.RuntimeError) {
      glue = null;
      loading = null;
      instanceGeneration += 1;
      const fatal = new Error(`the quantum simulator aborted and was reloaded: ${err.message}`);
      fatal.name = 'QuantumError';
      fatal.kind = 'aborted';
      throw fatal;
    }
    throw err;
  }
}

/**
 * Parse OpenQASM 3.
 *
 * Returns `{status: 'parsed', circuit, numQubits, numClbits, isClifford}` or
 * `{status: 'rejected', errors: [{kind, message, line, column}]}` — a rejected
 * program is the normal case while someone is typing, not an exception.
 *
 * @param {string} source
 * @param {Object<string, number>} [inputs] values for `input float` parameters
 */
export async function parse(source, inputs) {
  const wasm = await load();
  return JSON.parse(guard(() => wasm.parse(source, inputs ? JSON.stringify(inputs) : undefined)));
}

/** Canonical OpenQASM 3 of an IR circuit — the round-trip partner of `parse`. */
export async function toQasm3(circuit) {
  const wasm = await load();
  return guard(() => wasm.toQasm3(JSON.stringify(circuit)));
}

/** Whether the stabilizer tableau can run this circuit. */
export async function isClifford(circuit) {
  const wasm = await load();
  return guard(() => wasm.isClifford(JSON.stringify(circuit)));
}

/**
 * Run a circuit once.
 *
 * @param {Object} circuit IR circuit, as `parse` returns it
 * @param {Object} [options]
 * @param {number} [options.shots] 0 (the default) does not sample
 * @param {number} [options.seed] shot-stream seed; exact below 2^53
 * @param {'single'|'double'} [options.precision]
 * @param {number} [options.maxQubits] refusal ceiling, 24 by default
 * @param {'auto'|'statevector'|'stabilizer'} [options.method]
 * @param {boolean} [options.state] ask for the final state vector
 * @param {boolean} [options.probs] ask for every basis-state probability
 * @returns {Promise<{method: string, isClifford: boolean, numQubits: number,
 *   numClbits: number, shots: number, counts: ?Object<string, number>,
 *   state: ?Float64Array, probs: ?Float64Array, stateReason: ?string}>}
 *   `stateReason` explains why a requested state is absent — a measured circuit
 *   has no single state vector; step through it instead.
 */
export async function simulate(circuit, options) {
  const wasm = await load();
  return guard(() => wasm.simulate(JSON.stringify(circuit), options ? JSON.stringify(options) : undefined));
}

/**
 * Load a circuit into a live register for the Studio's time slider.
 *
 * The returned handle owns up to 256 MiB inside the wasm heap, which the
 * garbage collector cannot see: call `free()` when the view goes away.
 *
 * @param {Object} circuit IR circuit
 * @param {Object} [options] `{seed, precision, maxQubits}`
 * @returns {Promise<QuantumSimulator>}
 */
export async function createSimulator(circuit, options) {
  const wasm = await load();
  const inner = guard(() => new wasm.Simulator(
    JSON.stringify(circuit),
    options ? JSON.stringify(options) : undefined,
  ));
  return new QuantumSimulator(inner);
}

/**
 * A circuit held in a live register. Every method is synchronous: the module is
 * already instantiated by the time `createSimulator` resolves.
 */
export class QuantumSimulator {
  #inner;

  constructor(inner) {
    this.#inner = inner;
  }

  /**
   * Every call goes through here: a trap took the whole module with it, so the
   * handle points into an instance that no longer exists and has to be dropped
   * rather than called again.
   */
  #call(action) {
    if (!this.#inner) throw new Error('this simulator has been freed');
    try {
      return guard(() => action(this.#inner));
    } catch (err) {
      if (err && err.kind === 'aborted') this.#inner = null;
      throw err;
    }
  }

  get numQubits() { return this.#call((s) => s.numQubits); }

  get stepCount() { return this.#call((s) => s.stepCount); }

  /** How many steps have been applied. */
  get position() { return this.#call((s) => s.position); }

  get precision() { return this.#call((s) => s.precision); }

  get backendName() { return this.#call((s) => s.backendName); }

  get isClifford() { return this.#call((s) => s.isClifford); }

  /** Back to |0...0> with a cleared classical register. */
  rewind() { this.#call((s) => s.rewind()); }

  /** Apply the next operation; `false` once the program is exhausted. */
  step() { return this.#call((s) => s.step()); }

  runToEnd() { this.#call((s) => s.runToEnd()); }

  /**
   * The state after the fraction `t` of the PENDING operation, without
   * consuming it — the frames the time slider draws between two gates.
   * @param {number} t
   * @returns {Float64Array} interleaved `[re, im]`
   */
  stepFraction(t) { return this.#call((s) => s.stepFraction(t)); }

  /** @returns {Float64Array} interleaved `[re, im]` */
  amplitudes() { return this.#call((s) => s.amplitudes()); }

  /** @returns {Float64Array} one probability per basis state */
  probabilities() { return this.#call((s) => s.probabilities()); }

  /** @returns {Uint8Array} one byte per classical bit, index 0 = `c[0]` */
  clbits() { return this.#call((s) => s.clbits()); }

  /**
   * Bloch vectors of EVERY qubit, flattened `[x0, y0, z0, x1, y1, z1, ...]`.
   * This is the shape the per-qubit sphere row should use: the pass behind it
   * reads the whole state vector and yields all of them at once, so one call
   * costs what `bloch(0)` alone would cost.
   * @returns {Float64Array} `3 * numQubits` numbers
   */
  blochVectors() { return this.#call((s) => s.blochVectors()); }

  /**
   * The Bloch vector `[x, y, z]` of one qubit, served from the same cached pass
   * as `blochVectors` — cheap to repeat, but `blochVectors` says the intent.
   * @returns {Float64Array} three numbers
   */
  bloch(qubit) { return this.#call((s) => s.bloch(qubit)); }

  /**
   * Reduced density matrix of one or two qubits, row-major.
   * @param {number[]} qubits
   * @returns {Float64Array} interleaved `[re, im]`
   */
  reducedDensityMatrix(qubits) {
    return this.#call((s) => s.reducedDensityMatrix(Uint32Array.from(qubits)));
  }

  /**
   * Everything the run view draws at the current step. Complex numbers arrive
   * as `[re, im]` pairs.
   * @param {Object} [options] `{pairs, topK, probsTop}`; `pairs` is `'none'`,
   *   `'gate'`, `'all'` or a list of `[i, j]`
   */
  keyframe(options) {
    return JSON.parse(this.#call((s) => s.keyframe(options ? JSON.stringify(options) : undefined)));
  }

  /**
   * Sample the CURRENT state without collapsing it — the live histogram of the
   * run view. Keys name qubits, bit 0 rightmost.
   * @param {number} shots
   * @param {number} [seed] defaults to the simulator's seed
   * @returns {Object<string, number>}
   */
  counts(shots, seed) {
    return JSON.parse(this.#call((s) => s.counts(shots, seed)));
  }

  /** Release the wasm-side register. Safe to call twice. */
  free() {
    if (!this.#inner) return;
    const inner = this.#inner;
    this.#inner = null;
    try {
      inner.free();
    } catch {
      // A trapped instance has already dropped everything it owned.
    }
  }
}
